import { scope } from "arktype";

const schemas = scope({
  "Page<T>": {
    items: "T[]",
    total: "number",
    cursor: "string | null",
  },
  User: {
    id: "number",
    name: "string",
    email: "string",
  },
  Product: {
    id: "number",
    title: "string",
    price: "number",
  },
  PageOfUser: "Page<User>",
  PageOfProduct: "Page<Product>",
}).export();

export default schemas;

import schemas from "./schemas.ts";
import { TraversalError } from "arktype";

const schemaName = process.argv[2];

if (!schemaName || !(schemaName in schemas)) {
  console.error(`Unknown schema: ${schemaName}`);
  process.exit(1);
}

const schema = schemas[schemaName as keyof typeof schemas];

// Read stdin
const chunks: Buffer[] = [];
process.stdin.on("data", (chunk: Buffer) => {
  chunks.push(chunk);
});

process.stdin.on("end", () => {
  const input = Buffer.concat(chunks).toString("utf-8");
  let data: unknown;
  try {
    data = JSON.parse(input);
  } catch {
    console.error("Invalid JSON input");
    process.exit(1);
  }

  try {
    schema.assert(data);
    console.log("OK");
    process.exit(0);
  } catch (err) {
    if (err instanceof TraversalError) {
      console.error(err.message);
      process.exit(1);
    }
    throw err;
  }
});

